```python
from dataclasses import dataclass, field
from typing import Optional

@dataclass
class Applicant:
    years_experience: int
    degree: Optional[str] = None
    age: Optional[int] = None
    gaps: list[tuple[Optional[int], Optional[int]]] = field(default_factory=list)
    postcode: Optional[str] = None
    role_skills: list[str] = field(default_factory=list)
    required_skills: list[str] = field(default_factory=list)

    def score(self) -> float:
        if self.years_experience is None:
            years_score = 0
        elif self.years_experience >= 10:
            years_score = 100
        else:
            years_score = min(self.years_experience * 10, 100)

        degree_score = 0
        if self.degree:
            if self.degree.lower() in ("phd", "doctorate"):
                degree_score = 100
            elif self.degree.lower() in ("masters", "master's", "mphil"):
                degree_score = 75
            elif self.degree.lower().startswith("bachelor"):
                degree_score = 50
            else:
                degree_score = 25

        gap_score = 100
        total_gap_years = sum(
            (end or 9999) - start for start, end in self.gaps if start is not None
        )
        gap_score = max(0, 100 - (total_gap_years * 5))

        skill_match = 0
        if self.required_skills:
            matched = sum(1 for s in self.role_skills if s.lower() in [r.lower() for r in self.required_skills])
            skill_match = (matched / len(self.required_skills)) * 100

        raw = (years_score + degree_score + gap_score + skill_match) / 4
        return round(min(max(raw, 0), 100), 1)
